/* Last Shift 0.11: all controls and descriptions are inside the game viewport. */
(()=>{
 'use strict';
 const C=ShiftCore,R=ShiftRooms,D=ShiftMobileData,$=id=>document.getElementById(id);
 let robotWalk=null,robotNode='start';
 let roomCamera=null,cameraState=null,sceneArt=null,exploreView=null,focusZone=null,zoneNotes=[],hubCovered=0;
 const t=(ru,en)=>GameLocale.lang==='en'?en:ru;
 const phonePortrait=()=>innerHeight>innerWidth&&Math.min(innerWidth,innerHeight)<=600;
 let state=C.createState(),location='hub',orderActive=false,discovered=[],journalTab='items',modal=false,zoom=false,sound=false,lastTime=performance.now(),toastTimer,revealTimer;
 const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const score=n=>GameLocale.formatScore(n);
 function cargoSprite(id){const extra=D.extraIds.indexOf(id),n=extra>=0?extra:R.PLACEMENTS[id].atlas,cols=extra>=0?4:5,rows=extra>=0?3:2,src=extra>=0?D.cargoExtra:D.cargoOld;return `<span class="cargo-sprite" aria-hidden="true" style="background-image:url('${src}');--sprite-aspect:${extra>=0?.75:.6};--sheet-size:${cols*100}% ${rows*100}%;--sprite-pos:${n%cols/(cols-1)*100}% ${Math.floor(n/cols)/(rows-1)*100}%"></span>`;}
 function crate(){nav('crate');}
 function inspectCargo(id){const it=C.item(state,id);show(esc(it.name),`<p>${esc(it.description)}</p><div class="facts">${it.facts.map(f=>`<span>${esc(f)}</span>`).join('')}</div>`,[{label:t('Закрыть','Close'),run:close}],t('Уже в ящике','Already in the crate'));}
 const final=()=>['epilogue','ended'].includes(state.phase);
 const running=()=>state.phase==='playing'&&orderActive&&!modal&&!['luch','journal','crate'].includes(location)&&!document.hidden;
 function toast(t){clearTimeout(toastTimer);$('toast').textContent=t;$('toast').classList.add('visible');toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),3000);}
 function close(){modal=false;$('overlay').hidden=true;$('screen').inert=false;document.querySelector('.hud').inert=false;document.querySelector('.bottom-hud').inert=false;lastTime=performance.now();}
 function show(title,body,actions,kicker='ЛУЧ на связи'){modal=true;$('toast').classList.remove('visible');$('dialog-content').innerHTML=`<p class="dialog-kicker">${esc(kicker)}</p><h2 id="dialog-title">${title}</h2>${body}<div class="dialog-buttons">${actions.map((a,i)=>`<button class="btn ${a.secondary?'secondary':''}" data-modal="${i}" ${a.disabled?'disabled':''}>${a.label}</button>`).join('')}</div>`;actions.forEach((a,i)=>$('dialog-content').querySelector(`[data-modal="${i}"]`).addEventListener('click',a.run));$('overlay').hidden=false;$('screen').inert=true;document.querySelector('.hud').inert=true;document.querySelector('.bottom-hud').inert=true;$('dialog-content').querySelector('button:not(:disabled)')?.focus();}
 function nav(next){if(modal)return;if(!['hub','luch','journal','crate',...Object.keys(R.ROOMS)].includes(next))return;if(next!==location){focusZone=null;roomCamera?.destroy();roomCamera=null;cameraState=null;}location=next;zoom=false;state.history.push({event:'visit',screen:next});render();}
 function bind(id,fn){$(id)?.addEventListener('click',fn);}
 function render(){
  robotWalk?.destroy();robotWalk=null;
  sceneArt?.destroy();sceneArt=null;exploreView?.destroy();exploreView=null;$('game').classList.toggle('map-hub',location==='hub');$('game').classList.toggle('exploring',!!RoomExplore.ZONES[location]);
  if(roomCamera){cameraState=roomCamera.getState();roomCamera.destroy();roomCamera=null;}
  const o=C.currentOrder(state);$('home').hidden=location==='hub';$('home').setAttribute('aria-label',t('Вернуться в шлюз','Back to airlock'));$('journal-icon').classList.toggle('current',location==='journal');$('rating').textContent=score(C.rating(state));$('brief').textContent=final()?'Последнее решение: забрать память ЛУЧа?':orderActive?o.text:'ЛУЧ ждёт. Получи новое задание.';$('carry').textContent=state.carry?C.item(state,state.carry).name:'В руках ничего';$('carry').disabled=!state.carry;document.querySelectorAll('[data-nav]').forEach(b=>b.classList.toggle('current',b.dataset.nav===location));
  const z=RoomExplore.ZONES[location]?.find(x=>x.id===focusZone),portrait=phonePortrait(),size=RoomExplore.PORTRAIT_SIZES[location];let ratio=location==='luch'?(z?(portrait?864/1821:1.5):(portrait?size[0]/size[1]:2)):RoomExplore.ZONES[location]?(z?1.5*z.box[2]/z.box[3]:(portrait?size[0]/size[1]:1.5)):(innerWidth>=innerHeight?2:852/1846);FrameViewport.set(ratio,location==='hub');
  $('screen').className='screen';$('screen').innerHTML='';
  if(location==='hub'){
   $('screen-bg').src=D.hub;$('screen').innerHTML=HubMap.markup(R.ROOMS,t,final(),cargoCover());document.querySelectorAll('[data-room]').forEach(b=>b.addEventListener('click',()=>travel(b.dataset.room)));bind('hub-luch',()=>travel('luch'));bind('send',()=>travel('send'));bind('crate',()=>travel('crate'));animateCargo();
  }else if(location==='crate'){
   $('screen-bg').src=D.crate;$('screen').classList.add('crate-screen');
   $('screen').innerHTML=`<h1 class="screen-title">${t('Внутри ящика','Inside the crate')}</h1><div class="crate-cargo">${state.saved.map((id,i)=>`<button class="cargo-object" data-cargo="${id}" aria-label="Осмотреть: ${esc(C.item(state,id).name)}" style="--cargo-index:${i};left:${17+i*16}%;top:${35+(i%2)*2}%">${cargoSprite(id)}</button>`).join('')}</div>${state.saved.length?'':`<p class="empty-crate-note">${t('Пока пусто','Empty for now')}</p>`}<div class="crate-panel"><h2>${t('Груз: ','Cargo: ')}${state.saved.length}</h2><p>${state.carry?esc(C.item(state,state.carry).name):t('В руках ничего. Принеси вещь из отсека.','Empty hands. Bring an item from a room.')}</p><div class="panel-actions">${final()?`<button id="crate-depart" class="btn">${t('Отправиться в капсулу','Board the capsule')}</button>`:`<button id="crate-put" class="btn" ${!state.carry||!orderActive?'disabled':''}>${t('Положить вещь','Put the item inside')}</button>`}<button id="crate-back" class="btn secondary">${t('Вернуться в шлюз','Back to airlock')}</button></div></div>`;
   document.querySelectorAll('[data-cargo]').forEach(b=>b.addEventListener('click',()=>inspectCargo(b.dataset.cargo)));bind('crate-put',openGate);bind('crate-depart',openGate);bind('crate-back',()=>nav('hub'));
  }else if(location==='luch'){renderExplorer('luch');
  }else if(location==='journal'){
   $('screen-bg').src=D.luch;const entries=journalTab==='items'?discovered.map(id=>{const it=C.item(state,id);return `<article class="journal-entry"><h3>${esc(it.name)}</h3><small>${R.ROOMS[R.PLACEMENTS[id].room].name}${it.shipped?' · в ящике':''}</small><p>${esc(it.description)}</p><div class="facts">${it.facts.map(f=>`<span>${esc(f)}</span>`).join('')}</div></article>`;}).join('')||'<p>Пока записей нет. Осматривай вещи в отсеках: описание попадёт сюда.</p>':C.ORDERS.map((ord,i)=>{const result=state.results.find(r=>r.order===i),known=result||i===state.orderIndex&&orderActive;return known?`<article class="journal-entry"><h3>${esc(ord.title)}</h3><p>${esc(ord.text)}</p><small>${result?`${result.points}/100 · ${result.item?esc(C.item(state,result.item).name):'Не завершено'}`:'Текущее задание'}</small></article>`:'';}).join('')||'<p>Полученные задания появятся здесь.</p>';
   $('screen').innerHTML=`<h1 class="screen-title">Журнал</h1><div class="journal-panel"><div class="journal-tabs"><button id="tab-items" class="${journalTab==='items'?'selected':''}">Вещи ${discovered.length}/22</button><button id="tab-orders" class="${journalTab==='orders'?'selected':''}">Задания</button></div>${entries}${journalTab==='items'?zoneNotesMarkup():''}</div>`;bind('tab-items',()=>{journalTab='items';render();});bind('tab-orders',()=>{journalTab='orders';render();});
  }else{renderExplorer(location);}
  if(location==='hub'){sceneArt=HubMap.attach($('game'),$('screen-bg'),$('screen'),D);robotWalk=RobotRoute.attach($('hub-map-plane'),D.robot,robotNode,()=>modal||document.hidden);}
  if(['crate','journal'].includes(location))sceneArt=SceneArt.attach($('game'),$('screen-bg'),$('screen'),location==='journal'?'luch':location,D);
 }
 function travel(target){robotWalk?.go(target,node=>{robotNode=node;if(target==='send')openGate();else nav(target);});}
 function regionName(room){return room==='luch'?t('Кабинет ЛУЧа','LUCH office'):R.ROOMS[room].name;}
 function zoneText(zone,key='name'){return zone[key][GameLocale.lang==='en'?1:0];}
 function approach(id){focusZone=id;state.history.push({event:'approach',room:location,zone:id});render();}
 function lookZone(zone){const key=location+':'+zone.id;if(!zoneNotes.includes(key))zoneNotes.push(key);show(esc(zoneText(zone)),`<p>${esc(zoneText(zone,'note'))}</p>`,[{label:t('Закрыть','Close'),run:close}],t('Осмотр зоны · записано в журнал','Area inspection · recorded in memory'));}
 function zoneNotesMarkup(){if(!zoneNotes.length)return '';return `<h2>${t('Осмотренные зоны','Inspected areas')}</h2>`+zoneNotes.map(key=>{const [room,id]=key.split(':'),zone=RoomExplore.ZONES[room].find(z=>z.id===id);return `<article class="journal-entry"><h3>${esc(zoneText(zone))}</h3><small>${esc(regionName(room))}</small><p>${esc(zoneText(zone,'note'))}</p></article>`;}).join('');}
 function talkLuch(){const o=C.currentOrder(state),last=final();show(last?'Ещё один пассажир':esc(o.title),`<p>${last?'«Осталось отключить ненужное оборудование. Меня. Но можете сначала закончить уборку».':esc(o.intro)}</p><p>${last?'В техническом отделе доступен съёмный модуль памяти. Забери его к шлюзу, если хочешь улететь вместе.':esc(o.text)}</p>`,[{label:last?'Вернуться в шлюз':orderActive?'Выполнить задание':'Взять задание',run:()=>{if(!last&&!orderActive){orderActive=true;state.history.push({event:'assignment',order:state.orderIndex});}close();nav('hub');}},...(!last&&orderActive?[{label:'Уточнить',secondary:true,run:()=>show('Небольшое уточнение',`<p>${esc(C.hint(state))}</p><p>Верность команд не изменилась.</p>`,[{label:'Понятно',run:close}])}]:[])],t('ЛУЧ · часы остановлены','LUCH · clock paused'));}
 function cargoCover(){const c=RoomExplore.cargo(state.saved);return `<div class="cargo-wrap" data-cargo-count="${c.count}" aria-hidden="true"><svg viewBox="0 0 200 120"><defs><linearGradient id="cloth-paper" x2="0" y2="1"><stop stop-color="#fffbed"/><stop offset="1" stop-color="#dcd9cb"/></linearGradient><filter id="cloth-grain"><feTurbulence type="fractalNoise" baseFrequency=".6" numOctaves="2"/><feColorMatrix type="saturate" values="0"/><feComponentTransfer><feFuncA type="linear" slope=".08"/></feComponentTransfer><feBlend in="SourceGraphic" mode="multiply"/></filter></defs><g class="cloth-reveal" style="--covered:${hubCovered}%"><path d="M8 40 143 10 194 31 62 68 59 88Q46 94 38 82L6 60Z" fill="#34443922" transform="translate(2 4)"/><path d="M8 40 143 10 194 31 62 68 59 88Q46 94 38 82L6 60Z" fill="url(#cloth-paper)" stroke="#bfc0b0" stroke-width="1" filter="url(#cloth-grain)"/><path d="M8 40 62 68M62 68 194 31M29 38Q59 47 79 41M70 31Q98 42 120 35M109 24Q142 33 162 23M28 47 32 72M47 53 44 80M62 68 59 88" fill="none" stroke="#b6b9ad" opacity=".6" stroke-width="1.2"/>${c.ready?`<text x="105" y="33" text-anchor="middle" transform="rotate(-11 105 33)">${t('Готово','Ready to')}</text><text x="107" y="47" text-anchor="middle" transform="rotate(-11 107 47)">${t('к отправлению','ship')}</text>`:''}</g></svg></div>`;}
 function animateCargo(){const c=RoomExplore.cargo(state.saved),cloth=document.querySelector('.cloth-reveal');requestAnimationFrame(()=>requestAnimationFrame(()=>{if(cloth?.isConnected)cloth.style.setProperty('--covered',c.percent+'%');}));hubCovered=c.percent;}
 function renderExplorer(room){const zones=RoomExplore.ZONES[room],zone=zones.find(z=>z.id===focusZone)||null;if(!zone)focusZone=null;const portrait=phonePortrait(),detail=room==='luch'&&zone?D['luch'+zone.id[0].toUpperCase()+zone.id.slice(1)+(portrait?'Tall':'')]:null,overviewTall=portrait&&!zone,image=detail||(overviewTall?(room==='luch'?D.luch:D[room+'Tall']):room==='luch'?D.luchWide:R.ROOMS[room].image),portraitSize=RoomExplore.PORTRAIT_SIZES[room],iw=overviewTall?portraitSize[0]:room==='luch'&&!detail?1774:detail&&portrait?864:1536,ih=overviewTall?portraitSize[1]:room==='luch'&&!detail?887:detail&&portrait?1821:1024,available=room==='luch'?[]:R.visible(state,room),visibleIds=new Set(available.map(i=>i.id));$('screen-bg').src=image;$('screen').classList.add('explore-screen');$('home').setAttribute('aria-label',zone?t('Вернуться к общему плану','Back to room overview'):t('Вернуться в шлюз','Back to airlock'));
  $('home').title=$('home').getAttribute('aria-label');
  const patches=room==='luch'||overviewTall?'':state.items.filter(i=>R.PLACEMENTS[i.id].room===room&&!visibleIds.has(i.id)).map(it=>{const [l,y,w,h]=R.patchBox(it.id);return `<div class="clean-zone" style="left:${l}%;top:${y}%;width:${w}%;height:${h}%"><img alt="" src="${R.ROOMS[room].clean}" style="width:${10000/w}%;height:${10000/h}%;left:${-100*l/w}%;top:${-100*y/h}%"></div>`;}).join('');
  const targets=zone?available.filter(it=>zone.items.includes(it.id)).map(it=>{const [l,y,w,h]=R.PLACEMENTS[it.id].box;return `<button class="native-item" data-item="${it.id}" aria-label="Осмотреть: ${esc(it.name)}" style="left:${l}%;top:${y}%;width:${w}%;height:${h}%"></button>`;}).join(''):zones.map((z,i)=>{const [l,y,w,h]=overviewTall?RoomExplore.PORTRAIT_BOXES[room][z.id]:z.box;return `<button class="zone-entry" data-zone="${z.id}" aria-label="${t('Подойти: ','Approach: ')+esc(zoneText(z))}" style="left:${l+w/2}%;top:${y+h/2}%">${i+1}</button>`;}).join('');
  $('screen').innerHTML=`<h1 class="screen-title">${esc(regionName(room))}</h1><div class="explore-layout" id="explore-layout"><div class="explore-canvas" id="explore-canvas"><div class="explore-plane" id="explore-plane"><img src="${image}" alt="${esc(regionName(room))}">${patches}${targets}</div></div><div class="explore-controls" id="explore-controls">${zone?`<h2 class="explore-zone-name">${esc(zoneText(zone))}</h2><div class="explore-toolbar"><button id="room-overview">${t('← Общий план','← Room overview')}</button><button id="zone-look">${t('Осмотреть место','Inspect the area')}</button><button id="scene-zoom-out" aria-label="${t('Уменьшить изображение','Zoom image out')}">−</button><button id="scene-zoom-in" aria-label="${t('Увеличить изображение','Zoom image in')}">+</button>${room==='luch'&&zone.id==='desk'?`<button id="talk-luch">${t('Поговорить с ЛУЧом','Talk to LUCH')}</button>`:room!=='luch'?'<button id="search-help">Помочь с поиском</button>':''}</div>`:`<p class="explore-caption">${t('Общий план · нажми на стрелку или название зоны','Room overview · tap an arrow or area name')}</p><div class="zone-grid">${zones.map((z,i)=>`<button data-zone="${z.id}"><span>${i+1} ↗</span>${esc(zoneText(z))}</button>`).join('')}</div>`}</div></div>`;
  document.querySelectorAll('[data-zone]').forEach(b=>b.addEventListener('click',()=>approach(b.dataset.zone)));document.querySelectorAll('[data-item]').forEach(b=>b.addEventListener('click',()=>inspect(C.item(state,b.dataset.item))));bind('room-overview',()=>{focusZone=null;render();});bind('zone-look',()=>lookZone(zone));bind('talk-luch',talkLuch);bind('search-help',()=>{clearTimeout(revealTimer);$('explore-plane').classList.add('reveal');revealTimer=setTimeout(()=>$('explore-plane')?.classList.remove('reveal'),4500);toast('Вещи отмечены на несколько секунд. Штрафа нет.');});exploreView=RoomExplore.attach($('explore-layout'),$('explore-canvas'),$('explore-plane'),$('explore-controls'),iw,ih,detail?[0,0,100,100]:zone?.box||[0,0,100,100]);bind('scene-zoom-out',()=>exploreView?.zoom(exploreView.getZoom()/1.25));bind('scene-zoom-in',()=>exploreView?.zoom(exploreView.getZoom()*1.25));
 }

 function inspect(it){if(!discovered.includes(it.id)){discovered.push(it.id);state.history.push({event:'inspect',item:it.id});}show(esc(it.name),`<p>${esc(it.description)}</p><div class="facts">${it.facts.map(f=>`<span>${esc(f)}</span>`).join('')}</div><p class="dialog-kicker">Записано в журнал. Время остановлено.</p>`,[{label:'Закрыть',secondary:true,run:()=>{close();render();}},...(state.carry===it.id?[{label:'Вернуть на место',run:()=>{R.returnHome(state);close();render();}}]:[{label:state.carry?'Руки заняты':!orderActive&&!final()?'Сначала получи задание':'Взять с собой',disabled:!!state.carry||!orderActive&&!final(),run:()=>{if(C.pickup(state,it.id)){state.history.push({event:'pickup',item:it.id});close();render();toast('Вещь в руках. Вернись в шлюз.');}}}])],'Осмотр');}
 function openGate(){if(final()){const rescue=state.carry==='memory';show(rescue?'Место для двоих':'Отправиться одному?',`<p>${rescue?'«По инструкции здесь должен быть только один пассажир».':'ЛУЧ останется на станции. Можно вернуться за его памятью в технический отдел.'}</p><p>Этот выбор не меняет рейтинг.</p>`,[{label:'Ещё побуду',secondary:true,run:close},{label:rescue?'Забрать ЛУЧа и улететь':'Улететь одному',run:()=>{C.finish(state);close();ending();}}]);return;}if(!orderActive){toast('Сначала получи задание у ЛУЧа.');return;}if(!state.carry){toast('Принеси вещь из отсека.');return;}const it=C.item(state,state.carry);show('Сложить в ящик?',`<p><b>${esc(it.name)}</b></p><p>${esc(C.currentOrder(state).text)}</p>`,[{label:'Ещё подумаю',secondary:true,run:close},{label:'Положить',run:submit}],'Грузовой шлюз');}
 function submit(){close();const r=C.submit(state);if(r.type==='accepted')orderActive=false;render();if(r.type==='wrong'){show('Не совсем по инструкции',`<p>${esc(r.text)}</p><p>Вещь вернулась в свой отсек. За эту попытку −10 баллов. Можно исправиться.</p><p>Проверь запись о ней в журнале.</p>`,[{label:'Исправлюсь',run:close}]);}else if(r.type==='accepted'){orderActive=false;show('Команда выполнена',`<p>${esc(r.text)}</p><p><b>${r.points}/100 за поручение.</b></p>`,[{label:r.finished?'Последний разговор':'К ЛУЧу за следующим',run:()=>{close();nav('hub');travel('luch');}}]);}}
 function ending(){show(state.rescued?'Последняя смена. Вместе.':'Курс домой',`<div class="score-result">${score(C.rating(state))}</div><p>${state.rescued?'Робот подвигается. В капсуле нашлось место для двоих.':'«Хорошей дороги, маленький». Голос ЛУЧа становится тише.'}</p><table class="results">${state.results.map(r=>`<tr><td>${esc(C.ORDERS[r.order].title)}<span class="result-item">${r.item?esc(C.item(state,r.item).name):'Не завершено'}</span></td><td>${r.points}/100</td></tr>`).join('')}</table>`,[{label:'Журнал смены JSON',secondary:true,run:download},{label:'Ещё одна смена',run:restart}],'Верность команд');}
 function download(){const log={game:'Последняя смена',version:'0.12',rating:C.rating(state),orders:state.results,discovered,zoneNotes,events:state.history,rescued:state.rescued};const url=URL.createObjectURL(new Blob([JSON.stringify(log,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='last-shift-mobile-playtest.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 function restart(){close();state=C.createState();location='hub';orderActive=false;discovered=[];zoneNotes=[];focusZone=null;hubCovered=0;robotNode='start';zoom=false;render();intro();}
 function intro(){show('Последняя смена','<p>Все люди эвакуированы. Остались ты и ЛУЧ.</p><p>Получай задания у ЛУЧа, переходи в отсеки через шлюз и осматривай вещи. За один раз можно нести одну.</p><p>22 похожих предмета. Пять минут поиска. Осмотр, журнал и разговоры останавливают часы.</p><p>При входе видна вся комната. Нажми на стрелку или название зоны, чтобы подойти. «Общий план» возвращает назад. У ЛУЧа подойди к рабочему столу, чтобы получить поручение.</p>',[{label:t('Войти на станцию','Enter the station'),run:()=>{C.start(state);close();render();}}],'Тёплая история на станции «Вереск»');}
 function pause(){if(modal||state.phase!=='playing')return;show('Небольшой перерыв','<p>Время остановлено. Вещи остаются на своих местах.</p>',[{label:'Продолжить',run:close},{label:'Начать заново',secondary:true,run:restart}]);}
 bind('pause',pause);bind('carry',()=>{if(state.carry)inspect(C.item(state,state.carry));});bind('brief',()=>{const o=C.currentOrder(state);show(final()?'Ещё один пассажир':orderActive?o.title:'ЛУЧ ждёт',`<p>${final()?'Спаси память ЛУЧа из технического отдела или отправляйся один.':orderActive?esc(o.text):'Зайди к ЛУЧу и возьми задание.'}</p>`,[{label:'Закрыть',run:close},{label:'К ЛУЧу',secondary:true,run:()=>{close();nav('hub');travel('luch');}}]);});bind('rating',()=>show('Верность команд','<p>За поручение — 100 баллов. Каждая подтверждённая ошибочная отправка отнимает 10, минимум 0. Незавершённое поручение — 0.</p><p>Все подходящие трактовки равноценны. Итог — среднее четырёх поручений. Подсказки, поиск и финальный выбор баллы не отнимают.</p>',[{label:'Понятно',run:close}]));bind('help',()=>show('Как играть','<p>ЛУЧ выдаёт задания. Шлюз ведёт в четыре отсека и отправляет груз. Журнал хранит описания осмотренных вещей и задания.</p><p>Нажми на предмет, осмотри, возьми и вернись в шлюз. Вещь в руках можно осмотреть или вернуть кнопкой внизу.</p><p>В кабинете ЛУЧа четыре отдельных вида, в остальных комнатах пять зон. Подойди к зоне нажатием на стрелку или название, затем ищи предметы. «Общий план» отдаляет камеру. В шлюзе ткань закрывает ящик на четверть за каждый принятый предмет. «Помочь с поиском» работает внутри зоны без штрафа.</p>',[{label:'Понятно',run:close}]));document.querySelectorAll('[data-nav]').forEach(b=>b.addEventListener('click',()=>nav(b.dataset.nav)));
 bind('journal-icon',()=>nav('journal'));bind('home',()=>{if(focusZone&&RoomExplore.ZONES[location]){focusZone=null;render();}else nav('hub');});
 window.addEventListener('blur',pause);document.addEventListener('visibilitychange',()=>{if(document.hidden)pause();});window.addEventListener('keydown',e=>{if(e.code==='Escape'){if(!modal&&focusZone){focusZone=null;render();return;}if(modal&&state.phase==='playing')close();else pause();}});
 setInterval(()=>{const now=performance.now(),dt=Math.min(1,(now-lastTime)/1000);lastTime=now;if(running()&&C.tick(state,dt)){orderActive=false;if(state.carry)R.returnHome(state);location='luch';render();show('Время смены вышло','<p>Незавершённые поручения получили 0. Капсула ждёт. Можно спасти ЛУЧа.</p>',[{label:'Последний разговор',run:close}]);}const t=Math.ceil(state.remaining);$('timer').textContent=`${String(Math.floor(t/60)).padStart(2,'0')}:${String(t%60).padStart(2,'0')}`;$('timer').classList.toggle('urgent',t<60);},100);
 let lastPortrait=phonePortrait();window.addEventListener('resize',()=>{const next=phonePortrait();if(next!==lastPortrait){lastPortrait=next;if(RoomExplore.ZONES[location])render();}});
 render();intro();
})();
